contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    receive() external payable {}

    function test(address recipient) public {
        c.withdrawReward(address(this)); if (__ESBMC_reverted()) return;
        bool ok; c.withdrawReward(address(this)); bool __rev0 = __ESBMC_reverted(); if (__rev0) { ok = false; } else { ok = true; }
        assert(ok);
    }
}

